    "correctAnswer": "A",
    "explanation": "Choice A is the best answer. The sentence effectively describes the rocking chair to an audience unfamiliar with Sam Maloof, noting its sleek, contoured armrests and seat and explaining that Sam Maloof (the walnut chair’s creator) was an American woodworker.\n Choice B is incorrect. While the sentence explains who Sam Maloof was and mentions a chair, it doesn’t describe the chair.\n Choice C is incorrect.\nWhile the sentence explains who Sam Maloof was, it doesn’t describe the rocking chair.\n Choice D is incorrect. While the sentence describes the rocking chair, it doesn’t explain who Sam Maloof was."
