    "section": "rw",
    "domainId": "expression-ideas",
    "domainName": "3. Expression of Ideas",
    "subtopicId": "rhetorical-synthesis",
    "subtopic": "Rhetorical synthesis (notes)",
    "difficulty": "medium",
    "passage": "While researching a topic, a student has taken the following notes:\n• Novelist Willa Cather grew up in Nebraska and attended the University of Nebraska-Lincoln.\n• Some of Cather’s best-known novels are set in Nebraska.\n• Two such novels are O Pioneers! (1913) and My Ántonia (1918).\n• Cather’s novels describe the experiences of immigrants who settled in the Great Plains.",
