    "section": "rw",
    "domainId": "expression-ideas",
    "domainName": "3. Expression of Ideas",
    "subtopicId": "rhetorical-synthesis",
    "subtopic": "Rhetorical synthesis (notes)",
    "difficulty": "medium",
    "passage": "While researching a topic, a student has taken the following notes:\n• John Carver was one of the 41 signatories of the Mayflower Compact.\n• The Mayflower Compact was a legal agreement among the pilgrims that immigrated to Plymouth Colony.\n• It was created in 1620 to establish a common government.\n• It states that the pilgrims who signed it wanted to “plant the first colony in the northern parts of Virginia” under King James.\n• Carver became the first governor of Plymouth Colony.",
