    "section": "rw",
    "domainId": "expression-ideas",
    "domainName": "3. Expression of Ideas",
    "subtopicId": "rhetorical-synthesis",
    "subtopic": "Rhetorical synthesis (notes)",
    "difficulty": "medium",
    "passage": "While researching a topic, a student has taken the following notes:\n• Pterosaurs were flying reptiles that existed millions of years ago.\n• In a 2021 study, Anusuya Chinsamy-Turan analyzed fragments of pterosaur jawbones located in the Sahara Desert.\n• She was initially unsure if the bones belonged to juvenile or adult pterosaurs.\n• She used advanced microscope techniques to determine that the bones had few growth lines relative to the bones of fully grown pterosaurs.\n• She concluded that the bones belonged to juveniles.",
