    "correctAnswer": "C",
    "explanation": "Choice C is the best answer. It summarizes the information that describes the wok’s shape from the second and third bullet points.\n Choice A is incorrect. This choice doesn’t describe the shape of a wok.\n Choice B is incorrect. This choice doesn’t describe the shape of a wok, just some of its features.\n Choice D is incorrect. This choice doesn’t describe the shape of a wok, only some of its benefits or functions."
