    "id": "sat-rs-88308a39",
    "originalId": "88308a39",
    "section": "rw",
    "domainId": "expression-ideas",
    "domainName": "3. Expression of Ideas",
    "subtopicId": "rhetorical-synthesis",
    "subtopic": "Rhetorical synthesis (notes)",
    "difficulty": "medium",
    "passage": "While researching a topic, a student has taken the following notes:\n• Shaun Tan is an Australian author.\n• In 2008, he published Tales from Outer Suburbia, a book of fifteen short stories.\n• The stories describe surreal events occurring in otherwise ordinary suburban neighborhoods.\n• In 2018, he published Tales from the Inner City, a book of twenty-five short stories.\n• The stories describe surreal events occurring in otherwise ordinary urban settings.",
