    "explanation": "Choice C is the best answer. This is the only choice that makes a generalization about ultramarathons.\n Choice A is incorrect. This choice gives specific examples of ultramarathons but doesn’t say anything about them as a category. Choice B is incorrect. This choice compares marathons in general to one specific ultramarathon but doesn’t say anything about ultramarathons as a category.\n Choice D is incorrect. This choice contrasts two specific ultramarathons but doesn’t say anything about them as a category."
