    "section": "rw",
    "domainId": "expression-ideas",
    "domainName": "3. Expression of Ideas",
    "subtopicId": "rhetorical-synthesis",
    "subtopic": "Rhetorical synthesis (notes)",
    "difficulty": "medium",
    "passage": "While researching a topic, a student has taken the following notes:\n• Mary Kang is a Korean American portrait photographer.\n• She is based in New York City and in Austin, Texas.\n• One of Kang’s photographs features artist Dominique Fung.\n• In the portrait, Fung is seated on the floor.\n• Five of Fung’s paintings are resting against the wall behind her.",
