    "section": "rw",
    "domainId": "expression-ideas",
    "domainName": "3. Expression of Ideas",
    "subtopicId": "rhetorical-synthesis",
    "subtopic": "Rhetorical synthesis (notes)",
    "difficulty": "medium",
    "passage": "While researching a topic, a student has taken the following notes:\n• Architect Julian Abele studied Gregorian and neo-Gothic architecture in Europe.\n• Abele worked for an architecture firm that was hired in 1924 to design buildings for Duke University’s new campus.\n• Most of the buildings on Duke’s campus were designed in the Gregorian or neo-Gothic architectural styles.\n• At the time, Abele was not formally credited with designing the buildings.\n• Based on the buildings’ architectural styles, historians believe Abele designed most of the campus buildings.",
    "stem": "The student wants to specify why historians believe Abele designed most of Duke’s campus buildings. Which choice most effectively uses relevant information from the notes to accomplish this goal?",
    "type": "mcq",
    "options": [
      {
        "id": "A",
        "text": "Given that most of the buildings on Duke’s campus feature architectural styles that Abele had studied in Europe, historians believe Abele is the one who designed them."
      },
      {
        "id": "B",
        "text": "Though Abele wasn’t formally credited at the time, historians believe he designed most of the buildings on Duke’s campus."
      },
      {
        "id": "C",
        "text": "Most of Duke’s campus buildings, which were designed by a firm Abele worked for, were designed in the Gregorian and neo-Gothic architectural styles."
      },
      {
        "id": "D",
        "text": "Abele, an architect who studied Gregorian and neo-Gothic architecture in Europe, is believed to have designed most of the buildings on Duke’s campus."
      }
    ],
    "correctAnswer": "A",
    "explanation": "Choice A is the best answer. The sentence specifies why historians believe Abele designed most of Duke’s campus buildings, noting that most of the buildings feature architectural styles that Abele had studied.\n Choice B is incorrect. While the sentence explains that historians believe Abele designed most of Duke’s campus buildings, it doesn’t specify why historians hold that belief.\n Choice C is incorrect because the sentence emphasizes the architectural styles of Duke’s campus buildings; it doesn’t specify why historians believe Abele designed the buildings.\n Choice D is incorrect. While the sentence explains that Abele is believed to have designed most of the buildings on Duke’s campus, it doesn’t specify why historians believe that he designed the buildings."
