    "domainName": "3. Expression of Ideas",
    "subtopicId": "rhetorical-synthesis",
    "subtopic": "Rhetorical synthesis (notes)",
    "difficulty": "medium",
    "passage": "While researching a topic, a student has taken the following notes:\n• Planetary scientists classify asteroids based on their composition.\n• C-type asteroids are composed primarily of carbon.\n• They account for roughly 75 percent of known asteroids.\n• S-type asteroids are primarily made up of silicate minerals.\n• They account for roughly 17 percent of known asteroids.",
