    "correctAnswer": "C",
    "explanation": "Choice C is the best answer. The sentence emphasizes a similarity between the two sea tur tle species: both can be found in the Atlantic Ocean.\n Choice A is incorrect. The sentence indicates that the olive ridley sea tur tle is one of seven species of sea tur tle; it fails to mention the Kemp’s ridley sea tur tle.\n Choice B is incorrect. The sentence emphasizes a difference between the two sea tur tle species rather than a similarity. Choice D is incorrect. The sentence emphasizes a difference between the two sea tur tle species rather than a similarity."
